import type { DailyConsumptionObservation } from "../forecasting.types";

/**
 * Standard input payload provided to a forecasting model.
 */
export interface ForecastModelInput {
  productId: string;
  historicalData: DailyConsumptionObservation[];
  horizonDays: number;
  granularity?: "DAILY";
  referenceDate?: Date; // As-of date for beginning the forecast horizon
}

/**
 * Single predicted time-series point generated by a model.
 */
export interface ForecastModelPoint {
  periodStart: Date;
  periodEnd: Date;
  predictedQuantity: number;
  lowerBound?: number;
  upperBound?: number;
}

/**
 * Standard output returned by a forecasting model.
 */
export interface ForecastModelOutput {
  modelName: string;
  modelVersion: string;
  points: ForecastModelPoint[];
}

/**
 * Interface contract for pluggable, deterministic forecasting algorithms.
 * Allows replacing the baseline model with advanced ML models without altering
 * application orchestration or persistence layers.
 */
export interface IForecastingModel {
  readonly name: string;
  readonly version: string;

  /**
   * Generates deterministic point predictions and optional prediction intervals.
   */
  predict(input: ForecastModelInput): ForecastModelOutput;
}
